"""All custom CSS for LearnIQ. Colours are CSS variables so the theme is easy to change."""
import streamlit as st
CSS = '\n@import url(\'https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@400;500;600;700;800&display=swap\');\n:root{\n  --primary:#3730a3; --primary-mid:#6366f1; --primary-light:#eef2ff;\n  --background:#f4f6fb; --card:#ffffff; --text:#0f172a; --muted:#64748b;\n  --success:#16a34a; --success-bg:#dcfce7; --warning:#b45309; --warning-bg:#fef3c7;\n  --danger:#dc2626; --danger-bg:#fee2e2; --info:#475569; --info-bg:#e2e8f0;\n  --border:#e2e8f0; --sidebar:#1e1b4b; --radius:14px;\n  --shadow:0 1px 2px rgba(15,23,42,.04),0 4px 14px rgba(15,23,42,.05);\n}\n.stApp{background:var(--background);color:var(--text);font-family:\'Plus Jakarta Sans\',system-ui,sans-serif;}\nbutton,input,textarea,select{font-family:inherit;}\n#MainMenu,footer,[data-testid="stToolbar"],[data-testid="stDecoration"],[data-testid="stSidebarHeader"]{display:none !important;}\n[data-testid="stHeader"]{background:transparent;}\n.block-container{padding:1.4rem 2.2rem 2rem 2.2rem !important;max-width:100% !important;}\n\n/* ---------- sidebar ---------- */\nsection[data-testid="stSidebar"]{width:270px !important;min-width:270px !important;background:var(--sidebar);}\nsection[data-testid="stSidebar"] > div{padding-top:.4rem;}\nsection[data-testid="stSidebar"] .stButton button{\n  width:100%;justify-content:flex-start;background:transparent;border:0;border-radius:10px;\n  color:#c7cdf0;font-weight:500;padding:.55rem .8rem;box-shadow:none;}\nsection[data-testid="stSidebar"] .stButton button:hover{background:rgba(255,255,255,.08);color:#fff;}\nsection[data-testid="stSidebar"] .stButton button[kind="primary"],\nsection[data-testid="stSidebar"] .stButton button[data-testid="stBaseButton-primary"],\nsection[data-testid="stSidebar"] .stButton button[data-testid="baseButton-primary"]{\n  background:rgba(255,255,255,.15);color:#fff;font-weight:700;box-shadow:inset 3px 0 0 #a5b4fc;}\nsection[data-testid="stSidebar"] .stButton button p{font-size:.92rem;}\n\n/* ---------- custom page-link navigation ---------- */\nsection[data-testid="stSidebar"] [data-testid="stPageLink"]{\n  width:100%;\n  margin:.08rem 0;\n}\nsection[data-testid="stSidebar"] [data-testid="stPageLink"] a{\n  display:flex !important;\n  align-items:center !important;\n  width:100% !important;\n  min-height:40px !important;\n  box-sizing:border-box !important;\n  padding:.55rem .8rem !important;\n  border-radius:10px !important;\n  color:#e5e7eb !important;\n  background:transparent !important;\n  text-decoration:none !important;\n  font-size:.92rem !important;\n  font-weight:500 !important;\n}\nsection[data-testid="stSidebar"] [data-testid="stPageLink"] a:hover{\n  background:rgba(255,255,255,.10) !important;\n  color:#ffffff !important;\n}\nsection[data-testid="stSidebar"] [data-testid="stPageLink"] a[aria-current="page"]{\n  background:rgba(255,255,255,.16) !important;\n  color:#ffffff !important;\n  font-weight:700 !important;\n  box-shadow:inset 3px 0 0 #a5b4fc !important;\n}\nsection[data-testid="stSidebar"] [data-testid="stPageLink"] a p,\nsection[data-testid="stSidebar"] [data-testid="stPageLink"] a span{\n  color:inherit !important;\n}\n.brand{padding:.9rem .5rem .6rem .5rem;}\n.brand-name{color:#fff;font-size:1.55rem;font-weight:800;letter-spacing:-.02em;}\n.brand-name span{color:#a5b4fc;}\n.brand-sub{color:#a5b4fc;font-size:.78rem;margin-top:.1rem;}\n.side-foot{color:#a5b4fc;font-size:.75rem;padding:.6rem .6rem 0 .6rem;border-top:1px solid rgba(255,255,255,.12);margin-top:.8rem;}\n\n/* ---------- login ---------- */\n.login-wrap{max-width:560px;margin:5vh auto 1.2rem auto;text-align:center;}\n.login-card{background:var(--card);border:1px solid var(--border);border-radius:18px;box-shadow:var(--shadow);padding:2rem 2rem 1.35rem;}\n.login-brand{font-size:2rem;font-weight:800;color:#fff;background:var(--primary);display:inline-block;padding:.35rem .9rem;border-radius:12px;}\n.login-brand span{color:#a5b4fc;}\n.login-subtitle{color:var(--muted);font-size:.82rem;margin-top:.65rem;}\n.login-title{font-size:1.5rem;font-weight:800;margin-top:1.25rem;}\n.login-help{color:var(--muted);font-size:.88rem;margin-top:.3rem;}\n.login-demo{color:var(--muted);font-size:.76rem;text-align:center;margin-top:.8rem;}\n.sidebar-divider{border-top:1px solid rgba(255,255,255,.12);margin-top:.8rem;padding-top:.2rem;}\nsection[data-testid="stSidebar"] .stButton button{color:#e5e7eb !important;}\nsection[data-testid="stSidebar"] .stButton button:hover{color:#fff !important;background:rgba(255,255,255,.10) !important;}\n\n/* ---------- header ---------- */\n.breadcrumb{color:#64748b;font-size:.76rem;font-weight:600;margin-bottom:.18rem;}\n.page-title{font-size:1.6rem;font-weight:800;letter-spacing:-.02em;line-height:1.2;}\n.page-tag{color:var(--muted);font-size:.9rem;margin-top:.15rem;}\n.status{display:inline-flex;align-items:center;gap:.4rem;background:var(--warning-bg);color:var(--warning);\n  border-radius:999px;padding:.3rem .8rem;font-size:.8rem;font-weight:600;white-space:nowrap;}\n.status i{width:8px;height:8px;border-radius:50%;background:#f59e0b;display:inline-block;}\n.lede{color:var(--muted);font-size:.95rem;margin:.2rem 0 1rem 0;}\ndiv[data-baseweb="select"] > div{border-radius:10px;border-color:var(--border);background:#fff;}\n\n/* ---------- cards ---------- */\ndiv[class*="st-key-card_"]{background:var(--card);border:1px solid var(--border);border-radius:var(--radius);\n  box-shadow:var(--shadow);padding:1.1rem 1.25rem;}\n.sec{margin-bottom:.5rem;}\n.sec-title{font-size:1.02rem;font-weight:700;}\n.sec-sub{color:var(--muted);font-size:.82rem;}\n.kpi,.insight,.tile,.topic,.cluster,.result-box{background:var(--card);border:1px solid var(--border);border-radius:var(--radius);box-shadow:var(--shadow);}\n.kpi{padding:1rem 1.1rem;}\n.kpi-top{display:flex;justify-content:space-between;align-items:center;}\n.kpi-label{color:var(--muted);font-size:.8rem;font-weight:600;}\n.kpi-value{font-size:1.75rem;font-weight:800;letter-spacing:-.02em;margin:.3rem 0 .1rem 0;}\n.kpi-sub{color:var(--muted);font-size:.78rem;}\n.ico{width:30px;height:30px;border-radius:9px;display:inline-flex;align-items:center;justify-content:center;font-size:.95rem;}\n.ico.primary{background:var(--primary-light);color:var(--primary);}\n.ico.success{background:var(--success-bg);color:var(--success);}\n.ico.warning{background:var(--warning-bg);color:var(--warning);}\n.ico.danger{background:var(--danger-bg);color:var(--danger);}\n.ico.info{background:var(--info-bg);color:var(--info);}\n.insight{padding:1rem 1.2rem;border-left:4px solid var(--primary-mid);}\n.insight.success{border-left-color:var(--success);} .insight.warning{border-left-color:#f59e0b;}\n.insight.danger{border-left-color:var(--danger);}\n.insight-label{color:var(--muted);font-size:.8rem;font-weight:600;}\n.insight-value{font-size:1.25rem;font-weight:700;margin-top:.15rem;}\n.insight-sub{color:var(--muted);font-size:.8rem;}\n\n/* ---------- badges, progress, notes ---------- */\n.badge{display:inline-block;border-radius:999px;padding:.12rem .65rem;font-size:.75rem;font-weight:700;}\n.badge.success{background:var(--success-bg);color:var(--success);}\n.badge.warning{background:var(--warning-bg);color:var(--warning);}\n.badge.danger{background:var(--danger-bg);color:var(--danger);}\n.badge.info{background:var(--info-bg);color:var(--info);}\n.prog{margin:.7rem 0;}\n.prog-head{display:flex;justify-content:space-between;font-size:.86rem;margin-bottom:.3rem;}\n.bar{height:9px;background:#e8ecf4;border-radius:99px;overflow:hidden;}\n.fill{display:block;height:100%;border-radius:99px;background:var(--primary-mid);}\n.fill.success{background:var(--success);} .fill.warning{background:#f59e0b;} .fill.danger{background:var(--danger);}\n.note{background:var(--primary-light);color:var(--primary);border-radius:10px;padding:.55rem .85rem;font-size:.82rem;margin-top:.7rem;}\n\n/* ---------- tables ---------- */\n.tbl{width:100%;border-collapse:collapse;font-size:.88rem;}\n.tbl th{text-align:left;color:var(--muted);font-weight:600;font-size:.78rem;padding:.55rem .7rem;border-bottom:1px solid var(--border);}\n.tbl td{padding:.65rem .7rem;border-bottom:1px solid #f1f4f9;}\n.tbl tr.hl td{background:var(--primary-light);font-weight:600;}\n.tbl tr.hl td:first-child{box-shadow:inset 3px 0 0 var(--primary-mid);}\n\n/* ---------- feature specific ---------- */\n.result-box{padding:1.3rem 1.5rem;background:linear-gradient(135deg,#3730a3,#4f46e5);border:0;color:#fff;}\n.result-label{font-size:.85rem;opacity:.85;}\n.result-score{font-size:2.8rem;font-weight:800;letter-spacing:-.03em;line-height:1.1;}\n.result-row{display:flex;gap:2.2rem;margin-top:.8rem;flex-wrap:wrap;}\n.result-row div span{display:block;font-size:.75rem;opacity:.8;} .result-row div b{font-size:1.1rem;}\n.tile{padding:.8rem 1rem;} .tile-label{color:var(--muted);font-size:.78rem;} .tile-value{font-size:1.3rem;font-weight:700;}\n.topic{padding:1rem 1.1rem;margin-bottom:1rem;}\n.topic-head{display:flex;justify-content:space-between;align-items:center;}\n.topic-name{font-weight:700;font-size:1.02rem;}\n.topic-acc{font-size:1.9rem;font-weight:800;margin:.2rem 0 .5rem 0;}\n.topic-meta{color:var(--muted);font-size:.8rem;margin-top:.55rem;line-height:1.5;}\n.cluster{padding:1rem 1.1rem;border-top:4px solid var(--c);height:100%;}\n.cluster-name{font-weight:700;} .cluster-line{color:var(--muted);font-size:.84rem;}\n.rec{display:flex;align-items:center;gap:1rem;background:var(--card);border:1px solid var(--border);\n  border-radius:var(--radius);box-shadow:var(--shadow);padding:.9rem 1.2rem;margin-bottom:.7rem;}\n.rec-n{font-size:1.3rem;font-weight:800;color:var(--primary-mid);width:2.2rem;}\n.rec-body{flex:1;} .rec-title{font-weight:700;} .rec-reason{color:var(--muted);font-size:.84rem;}\n.rec-meta{display:flex;align-items:center;gap:.9rem;color:var(--muted);font-size:.82rem;}\n.cmp-row{display:flex;align-items:center;gap:.8rem;margin:.55rem 0;}\n.cmp-label{width:5.5rem;font-size:.85rem;color:var(--muted);} .cmp-bar{flex:1;}\n.delta{display:inline-block;background:var(--success-bg);color:var(--success);border-radius:999px;padding:.25rem .9rem;font-weight:800;}\n.delta.neg{background:var(--danger-bg);color:var(--danger);}\n\n/* ---------- main buttons ---------- */\n.stMain .stButton button{border-radius:10px;font-weight:600;border:1px solid var(--border);}\n.stMain .stButton button[kind="primary"],\n.stMain .stButton button[data-testid="stBaseButton-primary"],\n.stMain .stButton button[data-testid="baseButton-primary"]{background:var(--primary);color:#fff;border:0;padding:.55rem 1.4rem;}\n.stMain .stButton button[kind="primary"]:hover{background:#312e81;}\n@media (max-width:900px){.block-container{padding:1rem !important;}.rec{flex-wrap:wrap;}}\n'

def load_css():
    st.markdown(f'<style>{CSS}</style>', unsafe_allow_html=True)
